const image=document.querySelector('#device-screen');
const reduced=matchMedia('(prefers-reduced-motion: reduce)');
if(reduced.matches)image.src='media/dojo-screen-0.png';
for(const button of document.querySelectorAll('[data-screen]'))button.onclick=()=>{image.src=reduced.matches&&button.dataset.screen.endsWith('.gif')?'media/dojo-screen-0.png':button.dataset.screen;image.alt=button.textContent==='STEPS'?'Native Step Dojo: eight lanes, sixteen steps, velocity and nudge controls':button.textContent==='PUNCH'?'Native Punch FX page: eight effects':'Native Live Dojo: tempo, pixel ninja and performance controls';for(const b of document.querySelectorAll('[data-screen]'))b.setAttribute('aria-pressed',String(b===button));};
for(const audio of document.querySelectorAll('audio'))audio.addEventListener('play',()=>{for(const other of document.querySelectorAll('audio'))if(other!==audio)other.pause();});
let timer;const board=document.querySelector('.punch-board');
for(const button of document.querySelectorAll('[data-move]'))button.onclick=()=>{clearTimeout(timer);for(const b of document.querySelectorAll('[data-move]'))b.classList.remove('active');button.classList.add('active');board.classList.add('strike');document.querySelector('.impact-word').textContent=({ROLL:'SNARE-NADO!',STUTTER:'STUT-STUT!',REVERSE:'BACK OFF!',BRAKE:'VINYL KO!',FILTER:'SMOKE BOMB!',ECHO:'AND AGAIN!',CRUSH:'FILTHALITY!',GATE:'CHOP CHOP!'})[button.dataset.move];button.dataset.impact=document.querySelector('.impact-word').textContent;document.querySelector('#punch-saying').textContent=button.querySelector('small').textContent;timer=setTimeout(()=>{button.classList.remove('active');board.classList.remove('strike');},900);};
